            }
        }

        if active_ecosystems.contains(&Ecosystem::Npm) {
            if root.join("package-lock.json").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "package-lock.json",
                    "npm",
                    &["install", "--package-lock-only", "--ignore-scripts"],
