   522	                    stderr: output.redacted_stderr(),
   523	                }));
   524	            }
   525	        }
   526	
   527	        if !deleted.is_empty() {
   528	            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
   529	            let strs: Vec<String> = deleted.iter().map(|p| p.display().to_string()).collect();
   530	            for s in &strs {
   531	                args.push(s);
   532	            }
   533	            let output = runner.run("git", &args, root)?;
   534	            if !output.success() {
   535	                return Err(GraphError::Command(CommandError::Failed {
   536	                    program: "git".to_string(),
   537	                    exit_code: output.exit_code,
   538	                    stderr: output.redacted_stderr(),
   539	                }));
   540	            }
   541	        }
   542	
   543	        for path in &deferred_deletions {
   544	            let full = root.join(path);
   545	            if full.exists() {
   546	                fs::remove_file(&full).map_err(|e| GraphError::ApplyIo {
   547	                    path: path.clone(),
   548	                    message: e.to_string(),
   549	                })?;
   550	            }
   551	        }
   552	
   553	        if !deferred_deletions.is_empty() {
   554	            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
   555	            let strs: Vec<String> = deferred_deletions.iter().map(|p| p.display().to_string()).collect();
   556	            for s in &strs {
   557	                args.push(s);
   558	            }
   559	            let output = runner.run("git", &args, root)?;
   560	            if !output.success() {
   561	                return Err(GraphError::Command(CommandError::Failed {
   562	                    program: "git".to_string(),
   563	                    exit_code: output.exit_code,
   564	                    stderr: output.redacted_stderr(),
   565	                }));
   566	            }
   567	            modified_paths.extend(deferred_deletions.iter().cloned());
   568	        }
   569	
   570	        outcome.staged = modified_paths;
   571	    }
   572	
   573	    Ok(outcome)
   574	}
   575	
   310	}
