   312	/// Refuses when a canonical manifest version differs from `HEAD` while release inputs remain or the change is staged.
   313	pub fn check_partial_run<R: CommandRunner, D: DependencyResolver>(ws: &Workspace<'_, R, D>) -> Result<(), GraphError> {
   314	    let head = match ws.git_access().head_sha() {
   315	        Ok(head) => head,
   316	        Err(error) => {
   317	            let output = ws
   318	                .runner
   319	                .run("git", &["rev-parse", "--verify", "--quiet", "HEAD"], &ws.root)
   320	                .map_err(GraphError::Command)?;
   321	            match output.exit_code {
   322	                Some(1) => return Ok(()),
   323	                Some(0) => return Err(error.into()),
   324	                exit_code => {
   325	                    return Err(GraphError::Command(callisto_model::CommandError::Failed {
   326	                        program: "git".to_string(),
   327	                        exit_code,
   328	                        stderr: output.stderr,
   329	                    }))
   330	                }
   331	            }
   332	        }
   333	    };
   334	    let head = head.as_str();
   335	
   336	    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
   337	    let in_pre_release_cycle = ws.root.join(ws.config.pre_json_path()).exists();
   338	
   339	    let pending = !in_pre_release_cycle
   340	        && (head_has_pending_changeset(ws, head)?
   341	            || working_tree_has_pending_changeset(ws)?
   342	            || any_canonical_manifest_staged_uncommitted(ws)?);
   343	    if !pending {
   344	        return Ok(());
   345	    }
   346	
   347	    let cargo_root = if ws
   348	        .graph
   349	        .packages()
   350	        .flat_map(|pkg| pkg.canonical_manifests())
   351	        .any(|decl| decl.ecosystem() == callisto_model::Ecosystem::Cargo)
   352	    {
   353	        manifest_blob_at(ws, head, "Cargo.toml")?
   354	    } else {
   355	        None
   356	    };
   357	    let base_versions = ws.base_versions()?;
   358	    for pkg in ws.graph.packages() {
   359	        let Some(disk) = base_versions.get(&pkg.id) else {
   360	            continue;
   361	        };
   362	        for decl in pkg.canonical_manifests() {
   363	            let path = super::release_decision::normalized_git_path(&decl.path)?;
   364	            let Some(head_version) = manifest_version_at(ws, head, &path, cargo_root.as_deref())? else {
   365	                continue;
   366	            };
   367	            if *disk != head_version.version {
   368	                return Err(GraphError::PartialVersionRun {
   369	                    path: head_version.authority,
   370	                    disk: disk.clone(),
   371	                    head: head_version.version,
   372	                });
   373	            }
   374	        }
   375	    }
   376	
   377	    Ok(())
   378	}
